# Check if user has TL role
roles = [r.role for r in doc.roles]

if "Team Lead" in roles:
    # Check if User Permission already exists
    exists = frappe.db.exists("User Permission", {
        "user": doc.name,
        "allow": "Job Opening"
    })

    if not exists:
        up = frappe.get_doc({
            "doctype": "User Permission",
            "user": doc.name,
            "allow": "Job Opening",
            "for_value": doc.name,   # assuming Job Opening has "Assigned To" Link(User) field
            "apply_to_all_doctypes": 0
        })
        up.insert(ignore_permissions=True)
        frappe.msgprint(f"✅ User Permission created for {doc.name}")

def get_permission_query_conditions(user):
    if not user or user == "Administrator":
        return ""

    # Manager can see all
    if "Manager" in frappe.get_roles(user):
        return ""

    # Team Lead can only see assigned Job Openings
    if "Team Lead" in frappe.get_roles(user):
        return """`tabJob Opening`.name in (
                    select reference_name
                    from `tabToDo`
                    where reference_type = 'Job Opening'
                      and allocated_to = '{user}'
                      and status = 'Open'
                )""".format(user=user)

    # All other users see nothing
    return "1=0"
